7	const BASE_PREMIUMS: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	  rune: 25,
13	};
14	
15	const FIRST_INSURANCE_SURCHARGE = 1.1;
16	const PROCESSING_FEE = 5;
17	
18	const roundUpToWholeGold = (amount: number): number =>
19	  Math.ceil(Number(amount.toFixed(6)));
20	
21	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
22	  const basePremium = BASE_PREMIUMS[scenario.steps[0].items[0].type];
23	  const premium =
24	    roundUpToWholeGold(basePremium * FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
25	  return { results: [{ premium }] };
26	};
